function:ops.scac_mutation_registry_seal.definition_text:
declare v ops.scac_mutation_registry_version%rowtype; actual_count integer; actual_source_count integer;
        actual_set text; bad_hash boolean; category text; kind text; expected_registry text;
        actual_category_count integer; actual_category_digest text; expected jsonb; expected_catalog jsonb;
begin
  if p_registry_version not in ('scac-mutation-registry.v1','scac-mutation-registry.v2','scac-mutation-registry.v3','scac-mutation-registry.v4') then return false; end if;
  expected_registry:=case p_registry_version
    when 'scac-mutation-registry.v1' then 'sha256:7cc2feacec82bf7cce2af9af309dc4ae9426922003471703af010f6728957190'
    when 'scac-mutation-registry.v2' then 'sha256:d78696444c3f9d6dc9f82b71469986671b3846b762be7096ef4370bf4f6d609e'
    when 'scac-mutation-registry.v3' then 'sha256:b5b32aeb7c777cf726c5cb526a860a5b7d644afa54c3ce1fd55a42132fc0b298'
    when 'scac-mutation-registry.v4' then 'sha256:1bdf011d492a611eb528ddb907292871d099fea507e4fca11646978944a42c91' end;
  expected_catalog:=case p_registry_version
    when 'scac-mutation-registry.v1' then '{"projection_version":"scac-db-catalog-projection.v1","secdef_execute":{"count":290,"digest":"sha256:92d1347b45ee669c97a8b21712684651ee67aa3a2af363fca7c3f3a25436a0b6"},"relation_dml":{"count":285,"digest":"sha256:53d12ebf83db4661b0e55eb81f91ab510c34828424a2b945b66c0286134b0b0b"},"column_dml":{"count":12,"digest":"sha256:607e31d990653776243350d001ca465234e321349b05259751f8231ae3c2c44f"}}'::jsonb
    when 'scac-mutation-registry.v2' then '{"projection_version":"scac-db-catalog-projection.v2","secdef_execute":{"count":294,"digest":"sha256:8e1f8ed8984bc1f1a627020d1b5b0384124c5e5adba79ac17df0b21702bf6cc5"},"relation_dml":{"count":285,"digest":"sha256:53d12ebf83db4661b0e55eb81f91ab510c34828424a2b945b66c0286134b0b0b"},"column_dml":{"count":12,"digest":"sha256:607e31d990653776243350d001ca465234e321349b05259751f8231ae3c2c44f"},"role_authority":{"count":52,"digest":"sha256:345871802aa8f5b57aa87f3edfeac5187d06be0cb1ab5695371bcdfba4a49433"}}'::jsonb
    when 'scac-mutation-registry.v3' then '{"projection_version":"scac-db-catalog-projection.v3","secdef_execute":{"count":298,"digest":"sha256:d8306fc5bb4bd3348fe5197f0946c251c4f0486ecdf98914ba11a7af6e4682c5"},"relation_dml":{"count":285,"digest":"sha256:53d12ebf83db4661b0e55eb81f91ab510c34828424a2b945b66c0286134b0b0b"},"column_dml":{"count":12,"digest":"sha256:607e31d990653776243350d001ca465234e321349b05259751f8231ae3c2c44f"},"role_authority":{"count":52,"digest":"sha256:345871802aa8f5b57aa87f3edfeac5187d06be0cb1ab5695371bcdfba4a49433"}}'::jsonb
    when 'scac-mutation-registry.v4' then '{"projection_version":"scac-db-catalog-projection.v4","secdef_execute":{"count":302,"digest":"sha256:abe2fb9009736fa4ae47270fcf5d2153bbf3e7a8ed01de861cced9a1bb2fee82"},"relation_dml":{"count":285,"digest":"sha256:53d12ebf83db4661b0e55eb81f91ab510c34828424a2b945b66c0286134b0b0b"},"column_dml":{"count":12,"digest":"sha256:607e31d990653776243350d001ca465234e321349b05259751f8231ae3c2c44f"},"role_authority":{"count":52,"digest":"sha256:345871802aa8f5b57aa87f3edfeac5187d06be0cb1ab5695371bcdfba4a49433"}}'::jsonb end;
  select * into v from ops.scac_mutation_registry_version where registry_version=p_registry_version;
  if v.registry_version is null or v.registry_digest is distinct from expected_registry or
     v.catalog_projection is distinct from expected_catalog then return false; end if;
  select count(*),count(*) filter(where ingress_kind not in ('db_function_acl','db_relation_acl','db_column_acl')),
    'sha256:'||encode(public.digest(convert_to(coalesce(string_agg(entry_digest,',' order by ingress_key collate "C"),''),'UTF8'),'sha256'),'hex'),
    coalesce(bool_or(entry_digest is distinct from 'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(contract),'UTF8'),'sha256'),'hex')),false)
    into actual_count,actual_source_count,actual_set,bad_hash
    from ops.scac_mutation_registry_entry where registry_version=p_registry_version;
  if actual_count<>v.entry_count or actual_source_count<>v.source_entry_count or
     actual_set is distinct from v.entry_set_digest or bad_hash then return false; end if;
  for category,kind in values ('secdef_execute','db_function_acl'),('relation_dml','db_relation_acl'),('column_dml','db_column_acl') loop
    select count(*),'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(coalesce(jsonb_agg(contract-'effect_class'-'owner_package'-'implementation_state'-'classification_authorizing'-'source_locator' order by ingress_key collate "C"),'[]'::jsonb)),'UTF8'),'sha256'),'hex')
      into actual_category_count,actual_category_digest from ops.scac_mutation_registry_entry
      where registry_version=p_registry_version and ingress_kind=kind;
    expected:=v.catalog_projection->category;
    if actual_category_count<>(expected->>'count')::integer or actual_category_digest<>expected->>'digest' then return false; end if;
  end loop;
  return true;
end

function:ops.scac_policy_epoch_chain_sta.definition_text:
declare r ops.scac_policy_epoch%rowtype; expected bigint:=1; prior_digest text:=null; recomputed_source text; recomputed_epoch text; source jsonb; latest ops.scac_policy_epoch%rowtype;
begin
  for r in select * from ops.scac_policy_epoch order by epoch loop
    if r.epoch<>expected or (expected=1 and (r.previous_epoch is not null or r.previous_epoch_digest is not null))
       or (expected>1 and (r.previous_epoch<>expected-1 or r.previous_epoch_digest is distinct from prior_digest)) then
      return jsonb_build_object('valid',false,'reason','epoch_chain_gap_or_fork');
    end if;
    recomputed_source:='sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(jsonb_build_object(
      'registry_version',r.registry_version,'registry_digest',r.registry_digest,
      'doctrine_generation',r.doctrine_generation,'doctrine_projection_digest',r.doctrine_projection_digest,
      'rule_projection_digest',r.rule_projection_digest,
      'schema_applied_count',r.schema_applied_count,'schema_highest_migration',r.schema_highest_migration,
      'schema_ledger_digest',r.schema_ledger_digest)),'UTF8'),'sha256'),'hex');
    recomputed_epoch:=ops.scac_policy_epoch_digest(r.epoch,coalesce(r.previous_epoch,0),coalesce(r.previous_epoch_digest,'bootstrap'),recomputed_source,r.created_at);
    if r.registry_version<>'scac-mutation-registry.v2' or r.registry_digest<>'sha256:d78696444c3f9d6dc9f82b71469986671b3846b762be7096ef4370bf4f6d609e'
       or r.source_digest is distinct from recomputed_source or r.epoch_digest is distinct from recomputed_epoch
       or r.created_at>clock_timestamp()+interval '1 minute' then
      return jsonb_build_object('valid',false,'reason','epoch_digest_or_source_corrupt');
    end if;
    latest:=r; prior_digest:=r.epoch_digest; expected:=expected+1;
  end loop;
  if expected=1 then return jsonb_build_object('valid',false,'reason','epoch_ledger_unavailable'); end if;
  begin source:=ops.scac_policy_epoch_snapshot(); exception when others then
    return jsonb_build_object('valid',false,'reason','live_source_unavailable'); end;
  return jsonb_build_object('valid',true,'reason','valid','current_epoch',latest.epoch,
    'current_epoch_digest',latest.epoch_digest,'current_source_digest',latest.source_digest,
